CREATE TABLE datasets (
  key TEXT PRIMARY KEY CHECK (key IN ('kadra', 'wywiadowki', 'kontakty', 'dokumenty', 'partnerzy', 'oferty-pracy')),
  data_json TEXT NOT NULL CHECK (json_valid(data_json)),
