CREATE TABLE content_revisions_next (
  id TEXT PRIMARY KEY,
  entity TEXT NOT NULL CHECK (entity IN ('news', 'pages', 'datasets')),
  entity_id TEXT NOT NULL CHECK (length(entity_id) BETWEEN 1 AND 300),
  revision INTEGER NOT NULL CHECK (revision >= 1),
  data_json TEXT NOT NULL CHECK (json_valid(data_json)),
  actor_email TEXT,
  at TEXT NOT NULL,
  UNIQUE (entity, entity_id, revision)
);

INSERT INTO content_revisions_next (id, entity, entity_id, revision, data_json, actor_email, at)
SELECT id, entity, entity_id, revision, data_json, actor_email, at FROM content_revisions;

DROP TABLE content_revisions;

ALTER TABLE content_revisions_next RENAME TO content_revisions;

CREATE INDEX content_revisions_entity ON content_revisions (entity, entity_id);
